{"content":"import { useNavigate } from "@tanstack/react-router";
import { Search } from "lucide-react";
import { useState, type FormEvent } from "react";

export function SearchBar({
  size = "md",
  defaultValue = "",
  placeholder = "Search products, brands or part numbers",
}: {
  size?: "md" | "lg";
  defaultValue?: string;
  placeholder?: string;
}) {
  const [q, setQ] = useState(defaultValue);
  const navigate = useNavigate();

  function onSubmit(e: FormEvent) {
    e.preventDefault();
    navigate({ to: "/products", search: { q: q.trim(), category: "", brand: "" } });
  }

  const tall = size === "lg";

  return (
    <form onSubmit={onSubmit} role="search" className="w-full">
      <div className="flex w-full overflow-hidden rounded-md border border-input bg-card shadow-card focus-within:ring-2 focus-within:ring-ring">
        <label htmlFor={`search-${size}`} className="sr-only">
          Search products
        </label>
        <input
          id={`search-${size}`}
          value={q}
          onChange={(e) => setQ(e.target.value)}
          type="search"
          placeholder={placeholder}
          className={`w-full bg-transparent px-4 text-foreground outline-none placeholder:text-muted-foreground ${
            tall ? "h-14 text-base" : "h-11 text-sm"
          }`}
        />
        <button
          type="submit"
          className={`flex shrink-0 items-center gap-2 bg-sky px-5 font-semibold uppercase tracking-wide text-sky-foreground transition-colors hover:bg-navy ${
            tall ? "text-sm" : "text-xs"
          }`}
        >
          <Search className="h-4 w-4" aria-hidden />
          <span className="hidden sm:inline">Search</span>
        </button>
      </div>
    </form>
  );
}
